with r as (insert into releases(version, codename, released_on, summary) values ('Milestone', 'AI Practice Launch', '2025', 'We formalized AI & LLM Integration as a dedicated practice alongside our existing software development, academic projects, business IT, and mobile app work, in direct response to how much client demand had shifted toward chatbots, virtual assistants, and custom AI features.') returning id) insert into release_items select r.id, v.kind::release_item_kind, v.pos, v.body from r, (values ('highlight', 0, 'Stood up a dedicated AI & LLM Integration service line covering chatbots, virtual assistants, and custom model integrations.'), ('highlight', 1, 'Expanded academic project support to cover machine learning and AI-based final-year projects specifically.'), ('highlight', 2, 'Adopted retrieval-augmented generation as our default approach for grounding chatbot answers in a client''s real data.'), ('highlight', 3, 'Began building agentic automation workflows on top of LangChain and function-calling APIs from major model providers.'), ('highlight', 4, 'Crossed 100 engineers across our software development, IT solutions, and AI teams.')) as v(kind, pos, body);
