insert into agents(id, code, name, role, category_id, autonomy_level_id, description, sample_prompt, latency, accuracy, savings_multiplier, sort_order) values ('nmt-chat-support', 'NMT-CHAT-01', 'AI CUSTOMER SUPPORT CHATBOT', 'LLM-Powered Support & FAQ Assistant', (select id from agent_categories where name='Customer Support'), (select id from autonomy_levels where label='L4 - Autonomous'), 'Answers customer questions from your real documentation and order data, and escalates to a human with full context the moment it hits the edge of what it knows.', 'A customer is asking why their order hasn''t shipped yet and whether they can change the delivery address. Draft a helpful reply using our standard shipping policy.', '1.1s / reply', '96%', '50% Tickets Deflected', 0);
