insert into use_cases(id, title, department_id, tag_id, headline, problem, solution, sort_order) values ('uc-2', 'CUSTOM SOFTWARE REPLACES SPREADSHEET CHAOS', (select id from departments where name='Business IT'), (select id from tags where name='CUSTOM SOFTWARE'), 'REPLACED A PATCHWORK OF SPREADSHEETS WITH ONE CUSTOM SYSTEM', 'A logistics client was tracking inventory, orders, and vendor invoices across six disconnected spreadsheets, with no single source of truth and constant reconciliation errors.', 'We built a custom web application tailored to their exact workflow, consolidating inventory, orders, and invoicing into one system with role-based access and automated reporting.', 1);
