insert into use_cases(id, title, department_id, tag_id, headline, problem, solution, sort_order) values ('uc-3', 'FINAL-YEAR AI PROJECT, DELIVERED ON TIME', (select id from departments where name='Academic Projects'), (select id from tags where name='ACADEMIC'), 'AN ORIGINAL MACHINE LEARNING PROJECT BUILT TO THE STUDENT''S EXACT BRIEF', 'A final-year computer science student needed a machine learning project with genuinely original work behind it, not a reused template, and a tight submission deadline.', 'We scoped the project against the department''s evaluation criteria, built a custom recommendation model from the student''s own dataset, and prepared documentation the student could confidently defend in their viva.', 2);
