insert into use_cases(id, title, department_id, tag_id, headline, problem, solution, sort_order) values ('uc-4', 'MANUAL APPROVAL WORKFLOW REPLACED WITH AUTOMATION', (select id from departments where name='Business IT'), (select id from tags where name='BUSINESS IT'), 'CUT APPROVAL TURNAROUND FROM DAYS TO HOURS', 'A logistics company''s purchase-order approvals moved through email chains and spreadsheets, with no visibility into what was stuck where or who needed to sign off next.', 'We built a lightweight internal workflow tool that routes each request to the right approver automatically, sends reminders on stalled items, and gives finance a live dashboard of what''s pending.', 3);
