insert into use_cases(id, title, department_id, tag_id, headline, problem, solution, sort_order) values ('uc-5', 'MOBILE APP LAUNCHES WITH A BUILT-IN AI ASSISTANT', (select id from departments where name='Mobile App'), (select id from tags where name='MOBILE APP'), 'AI ASSISTANT LIVE AT LAUNCH, NOT BOLTED ON LATER', 'A wellness startup wanted a mobile app with an in-app assistant that could answer product questions and guide onboarding, but had no engineering team of their own to build either the app or the AI layer.', 'We built the iOS and Android app from a single codebase and wired in an LLM-powered assistant grounded in the client''s own content from day one, so it shipped with launch instead of arriving in a future update.', 4);
