insert into use_cases(id, title, department_id, tag_id, headline, problem, solution, sort_order) values ('uc-6', 'INTERNAL KNOWLEDGE ASSISTANT CUTS ONBOARDING TIME', (select id from departments where name='Internal Tools'), (select id from tags where name='AI & LLM'), 'NEW HIRES STOPPED PINGING SENIOR STAFF FOR ANSWERS ALREADY IN THE DOCS', 'A software team''s internal documentation was scattered across wikis, PDFs, and old Slack threads, so new hires spent their first weeks interrupting senior engineers for answers that already existed somewhere.', 'We built an internal assistant grounded in the company''s actual documentation and Slack history, so any employee can ask a plain-language question and get an answer sourced from real internal content, with a link back to where it came from.', 5);
