insert into case_studies(slug, title, description, industry_id, platform_type_id, image_url, published_on, metric_label, metric_value) values ('ai-chatbot-support-deflection', 'AI Chatbot Cuts Support Ticket Volume in Half', 'An e-commerce client''s support inbox was drowning in the same shipping and returns questions every day. We built an LLM-powered chatbot grounded in their own policies and live order data, and cut ticket volume in half within a month.', (select id from industries where name='E-commerce'), (select id from platform_types where name='AI & LLM Integration'), '/images/it-integrate.webp', '2025', 'Support Tickets Deflected', '50%');
insert into case_study_sections values ('ai-chatbot-support-deflection', 0, 'The challenge', 'The client''s small support team was fielding dozens of near-identical questions every day: where''s my order, can I change my address, what''s the return policy. Peak season made it worse, with response times stretching past a day and customer satisfaction sliding as a result.');
insert into case_study_sections values ('ai-chatbot-support-deflection', 1, 'The approach', 'We built a chatbot on top of an LLM backend, grounded in the client''s actual policy documents and connected live to their order-management system through retrieval-augmented generation, so answers reflected real data instead of a static script. We deployed it as a website widget and a WhatsApp integration, with a clean handoff to a human agent whenever a question fell outside its scope, full conversation history attached.');
insert into case_study_sections values ('ai-chatbot-support-deflection', 2, 'The outcome', 'Within a month of launch, the bot was resolving half of all incoming questions without a human touching them, and first-response time dropped from hours to under two seconds for anything it could handle directly. The support team redirected the time they got back toward the harder cases that actually needed a person, and customer satisfaction scores rose alongside the faster responses.');
insert into case_studies(slug, title, description, industry_id, platform_type_id, image_url, published_on, metric_label, metric_value) values ('custom-software-inventory-system', 'Custom Software Replaces a Six-Spreadsheet Mess', 'A logistics client was tracking inventory, orders, and vendor invoices across six disconnected spreadsheets. We built a single custom system around their actual workflow instead of forcing them into a generic off-the-shelf platform.', (select id from industries where name='Logistics'), (select id from platform_types where name='Custom Software Development'), '/images/image_3.webp', '2025', 'Manual Data Entry Reduced', '-65%');
insert into case_study_sections values ('custom-software-inventory-system', 0, 'The challenge', 'Inventory counts lived in one spreadsheet, purchase orders in another, and vendor invoices in a third, maintained by different people with no shared source of truth. Reconciling them at month-end regularly took days and still produced errors that rippled into the next cycle.');
insert into case_study_sections values ('custom-software-inventory-system', 1, 'The approach', 'Rather than recommending an off-the-shelf ERP that would have required the client to change how they actually operate, we mapped their existing workflow in detail and built a custom web application around it: one system for inventory, orders, and invoicing, with role-based access so each team only saw what was relevant to them, and automated reports replacing the manual month-end roll-up.');
insert into case_study_sections values ('custom-software-inventory-system', 2, 'The outcome', 'Manual data entry dropped by roughly two-thirds once information only had to be entered once instead of copied between spreadsheets, and reconciliation errors fell by a similar margin. The client''s ops team went from spending the first week of every month untangling the prior month''s numbers to reviewing a report that was already correct.');
insert into case_studies(slug, title, description, industry_id, platform_type_id, image_url, published_on, metric_label, metric_value) values ('mobile-app-ai-assistant', 'A Mobile App With a Built-In AI Assistant', 'A wellness startup needed a mobile app fast, and wanted an AI assistant baked in from day one rather than bolted on after launch. We delivered both together, on iOS and Android, in a single build.', (select id from industries where name='Health & Wellness'), (select id from platform_types where name='Mobile App Development'), '/images/image_2.webp', '2025', null, null);
insert into case_study_sections values ('mobile-app-ai-assistant', 0, 'The challenge', 'The client wanted a consumer app that could answer users'' wellness questions conversationally, not just serve static content, but had no in-house mobile or AI engineering team to build it, and a launch date that didn''t leave room for two separate build phases.');
insert into case_study_sections values ('mobile-app-ai-assistant', 1, 'The approach', 'We built the app cross-platform to cover iOS and Android from one codebase, with an in-app assistant powered by an LLM backend from the start, integrated with the app''s own content library through a retrieval pipeline so its answers stayed grounded in the client''s actual wellness guidance rather than generic advice.');
insert into case_study_sections values ('mobile-app-ai-assistant', 2, 'The outcome', 'The app shipped to both app stores on schedule with the AI assistant fully working at launch, not added as a later update. We''ve continued supporting the app post-launch, handling OS updates and new features as the client''s user base has grown.');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('platform', 'ai-chatbots-assistants', 'AI Chatbots & Assistants', 'CONVERSATIONAL AI THAT ACTUALLY HELPS', 'We design and build LLM-powered chatbots and virtual assistants that answer real questions with real data, on your website, inside your product, or across the messaging channels your customers already use.', 0);
insert into offering_sections values ('platform', 'ai-chatbots-assistants', 0, 'Trained on your business, not the whole internet', 'A generic chatbot only knows what''s public. Ours is grounded in your own documentation, product catalog, support history, and internal knowledge base through retrieval-augmented generation, so it answers with your actual policies and your actual data instead of a plausible-sounding guess.');
insert into offering_sections values ('platform', 'ai-chatbots-assistants', 1, 'From FAQ bot to full assistant', 'We build everything from a simple support widget that deflects the repetitive questions your team is tired of answering, to a full conversational assistant that can look up an order, walk a student through a project requirement, or triage a support ticket before a human ever sees it.');
insert into offering_sections values ('platform', 'ai-chatbots-assistants', 2, 'Wherever your customers already are', 'Web chat widget, WhatsApp, Slack, Microsoft Teams, or a custom in-app assistant, we build on the channel that fits your users, and connect it to the same LLM backend so the answers stay consistent everywhere.');
insert into offering_sections values ('platform', 'ai-chatbots-assistants', 3, 'Built to hand off gracefully', 'Every assistant we ship knows its own limits. When a question needs a human, it escalates with the full conversation context attached instead of leaving your customer to repeat themselves from scratch.');
insert into offering_stats values ('platform', 'ai-chatbots-assistants', 0, 'Typical first-response time', '< 2 sec');
insert into offering_stats values ('platform', 'ai-chatbots-assistants', 1, 'Common ticket deflection rate', '40-60%');
insert into offering_stats values ('platform', 'ai-chatbots-assistants', 2, 'Channels supported', 'Web, WhatsApp, Slack, Teams');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('platform', 'ai-automation-agents', 'AI Automation & Agents', 'AI THAT DOES THE WORK, NOT JUST SUGGESTS IT', 'Beyond answering questions, we build AI agents that take action: pulling data across your tools, filling out the repetitive parts of a workflow, and handing off to a person only for the decisions that actually need one.', 1);
insert into offering_sections values ('platform', 'ai-automation-agents', 0, 'From advice to execution', 'A chatbot that only suggests what to do still leaves someone clicking through five screens to do it. We build agents that carry out the multi-step task itself, reading data from one system, applying your business rules, and writing the result back to another, so the person on the other end gets a finished task, not a to-do list.');
insert into offering_sections values ('platform', 'ai-automation-agents', 1, 'Human-in-the-loop where it matters', 'Low-risk, repetitive steps run automatically. Anything with real weight, a refund, a data change, a message to a client, pauses for a quick human approval first, so you get the speed of automation without losing control over what actually goes out the door.');
insert into offering_sections values ('platform', 'ai-automation-agents', 2, 'Built on the frameworks doing the heavy lifting', 'We build agents with the current generation of agentic tooling, LangChain, LlamaIndex, and function-calling / tool-use APIs from providers like OpenAI, Anthropic, and Google, choosing whichever stack fits your existing systems best rather than forcing one tool everywhere.');
insert into offering_sections values ('platform', 'ai-automation-agents', 3, 'Where this pays off fastest', 'Internal reporting that used to mean copying numbers between three spreadsheets. Lead qualification that used to sit in an inbox overnight. Document processing that used to be a full-time job for someone new. These are exactly the repetitive, rules-heavy tasks agentic automation is built to absorb.');
insert into offering_stats values ('platform', 'ai-automation-agents', 0, 'Typical manual-hours saved / week', '10-25 hrs');
insert into offering_stats values ('platform', 'ai-automation-agents', 1, 'Workflows we''ve automated', 'Ticketing, reporting, data entry');
insert into offering_stats values ('platform', 'ai-automation-agents', 2, 'Human approval on high-impact steps', 'Always');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('platform', 'llm-integration', 'LLM Integration & Custom AI', 'YOUR PRODUCT, POWERED BY YOUR OWN AI', 'When off-the-shelf AI features aren''t enough, we integrate and fine-tune large language models directly into your product: custom prompting, retrieval pipelines, and, where it''s worth it, model fine-tuning built around your own data.', 2);
insert into offering_sections values ('platform', 'llm-integration', 0, 'The right model for the job, not just the biggest one', 'We work across the major model providers, OpenAI''s GPT models, Anthropic''s Claude, Google''s Gemini, and open-source options where self-hosting makes sense, and help you pick based on cost, latency, and the kind of task you''re actually solving, instead of defaulting to whichever model is loudest that quarter.');
insert into offering_sections values ('platform', 'llm-integration', 1, 'RAG pipelines that keep answers grounded', 'We build retrieval-augmented generation pipelines that connect an LLM to your own documents, database, or knowledge base, so responses are grounded in your real content instead of the model''s general training data, with citations back to the source when it matters.');
insert into offering_sections values ('platform', 'llm-integration', 2, 'Fine-tuning when it''s actually worth it', 'For teams with enough of their own data and a genuinely repetitive task, we fine-tune a smaller model to match, which usually means lower latency and lower cost per call than routing everything through the largest general-purpose model available.');
insert into offering_sections values ('platform', 'llm-integration', 3, 'Shipped like software, not a proof of concept', 'Every integration comes with proper API design, rate limiting, logging, and cost monitoring built in from day one, because an AI feature that works in a demo and falls over in production isn''t actually done.');
insert into offering_stats values ('platform', 'llm-integration', 0, 'Model providers we build with', 'OpenAI, Anthropic, Google, open-source');
insert into offering_stats values ('platform', 'llm-integration', 1, 'Typical integration timeline', '2-6 weeks');
insert into offering_stats values ('platform', 'llm-integration', 2, 'Delivered with logging & cost monitoring', 'Always');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('solution', 'ai-llm-integration', 'AI & LLM Integration', 'OUR MOST-REQUESTED SPECIALTY', 'Chatbots, virtual assistants, and LLM-powered features built into your product or business, grounded in your own data instead of generic answers pulled from nowhere.', 3);
insert into offering_sections values ('solution', 'ai-llm-integration', 0, 'What we actually build', 'Customer-facing chatbots that answer from your real documentation and order data. Internal assistants that let your team ask a question in plain language instead of digging through a dashboard. AI agents that take on a repetitive workflow end to end. Custom features built directly on top of GPT, Claude, or Gemini, wired into your existing product rather than bolted on as a separate widget.');
insert into offering_sections values ('solution', 'ai-llm-integration', 1, 'Grounded in your data, not just the model''s training', 'We build retrieval-augmented generation pipelines that connect the model to your own documents, product catalog, or database, so answers are sourced from what''s actually true for your business right now, with the option to fine-tune a smaller model for high-volume, narrowly scoped tasks where that''s more cost-effective.');
insert into offering_sections values ('solution', 'ai-llm-integration', 2, 'A team that ships AI features, not just demos', 'Every integration we deliver comes with the unglamorous parts done properly: rate limiting, error handling, logging, and cost monitoring, so the feature holds up once real traffic hits it instead of only working in a screen recording.');
insert into offering_sections values ('solution', 'ai-llm-integration', 3, 'Fits whatever you''re already running', 'Whether your product is a web app, a mobile app, or an internal tool, we integrate the AI layer into your existing stack rather than asking you to rebuild around it.');
insert into offering_stats values ('solution', 'ai-llm-integration', 0, 'Model providers we build with', 'OpenAI, Anthropic, Google');
insert into offering_stats values ('solution', 'ai-llm-integration', 1, 'Typical chatbot deployment', '2-4 weeks');
insert into offering_stats values ('solution', 'ai-llm-integration', 2, 'Delivered with monitoring & logging', 'Always');
insert into offering_stats values ('solution', 'ai-llm-integration', 3, 'Engineers with AI/LLM project experience', 'Growing team');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('solution', 'custom-software-development', 'Custom Software Development', 'END TO END, CONCEPT TO COMPLETION', 'We design, build, and ship custom software from the first requirements conversation through to a finished, production-ready product, not a template with your logo on it.', 4);
insert into offering_sections values ('solution', 'custom-software-development', 0, 'Built around your actual requirements', 'Every business runs a little differently, and off-the-shelf software rarely fits perfectly. We start by understanding what you actually need the software to do, then build around that instead of forcing your workflow to match someone else''s assumptions.');
insert into offering_sections values ('solution', 'custom-software-development', 1, 'From concept through to completion', 'We handle the full lifecycle: requirements and architecture, design, development, testing, and deployment, with regular check-ins along the way so you''re never waiting weeks to see what''s been built.');
insert into offering_sections values ('solution', 'custom-software-development', 2, '100% original, custom-built work', 'Every project is written for you specifically, not repurposed from a template or lifted from another client''s codebase. That matters whether you''re a business that needs software nobody else is running, or a student whose project needs to actually be their own original work.');
insert into offering_sections values ('solution', 'custom-software-development', 3, 'Timely delivery, transparent pricing', 'We agree on scope, timeline, and price upfront, and we keep you posted if anything shifts. No surprise invoices, and no silently slipping deadlines.');
insert into offering_stats values ('solution', 'custom-software-development', 0, 'Team of engineers', '100+');
insert into offering_stats values ('solution', 'custom-software-development', 1, 'Combined engineering experience', '10+ yrs');
insert into offering_stats values ('solution', 'custom-software-development', 2, 'Original, custom-built work', '100%');
insert into offering_stats values ('solution', 'custom-software-development', 3, 'Pricing', 'Transparent, agreed upfront');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('solution', 'academic-projects', 'Academic Projects', 'FINAL-YEAR PROJECTS, DONE PROPERLY', 'We help students plan and build final-year and academic projects that meet their exact brief, with original code and a level of technical depth that holds up under a viva or a demo defense.', 5);
insert into offering_sections values ('solution', 'academic-projects', 0, 'Built to your brief, not a stock template', 'We work from your actual project requirements, department guidelines, and evaluation criteria, and build something matched to them specifically, rather than reselling the same generic project to every student who asks.');
insert into offering_sections values ('solution', 'academic-projects', 1, 'Originality that can survive scrutiny', 'Every academic project we deliver is written from scratch for that student. We can walk through the architecture and the reasoning behind it, because it''s built to be understood and defended, not just handed over.');
insert into offering_sections values ('solution', 'academic-projects', 2, 'AI-powered projects are our specialty', 'A large share of the academic projects we take on now involve AI in some form: a chatbot, an LLM-based tool, a recommendation system, or a machine learning model. If your brief calls for AI and you''re not sure how to scope it, that''s exactly where we''re most useful.');
insert into offering_sections values ('solution', 'academic-projects', 3, 'Support through the whole timeline', 'From initial proposal and literature review through implementation, documentation, and presentation prep, we work to your submission deadline, not around it.');
insert into offering_stats values ('solution', 'academic-projects', 0, 'Focus', 'Originality & custom requirements');
insert into offering_stats values ('solution', 'academic-projects', 1, 'AI/ML project requests', 'Growing fast');
insert into offering_stats values ('solution', 'academic-projects', 2, 'Delivery', 'Matched to your deadline');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('solution', 'business-it-solutions', 'Business IT Solutions', 'IT CONSULTING, WEB, AND AUTOMATION', 'IT consulting, web design and development, and business process automation aimed at one outcome: less manual work, and systems that actually talk to each other.', 6);
insert into offering_sections values ('solution', 'business-it-solutions', 0, 'IT consulting that starts with your actual bottleneck', 'We look at where your team is losing time, duplicate data entry, disconnected tools, manual reporting, and recommend and build the fix, rather than selling a generic digital-transformation package regardless of what you actually need.');
insert into offering_sections values ('solution', 'business-it-solutions', 1, 'Web design and development', 'From marketing sites to full web applications, we design and build for your business specifically, with a focus on something that actually converts and holds up, not just something that looks good in a first draft.');
insert into offering_sections values ('solution', 'business-it-solutions', 2, 'Automation for the repetitive stuff', 'Data entry between systems, routine reports, approval workflows, we look for the manual steps eating your team''s time and replace them with automation, increasingly built with an AI layer where a workflow needs judgment, not just rules.');
insert into offering_sections values ('solution', 'business-it-solutions', 3, 'Digital transformation, at your pace', 'We don''t require a full platform rebuild to get started. Most engagements begin with one clear bottleneck, prove the approach works, and expand from there.');
insert into offering_stats values ('solution', 'business-it-solutions', 0, 'Services', 'Consulting, web, automation');
insert into offering_stats values ('solution', 'business-it-solutions', 1, 'Approach', 'Start small, prove it, expand');
insert into offering_stats values ('solution', 'business-it-solutions', 2, 'Support', 'Ongoing, not one-and-done');
insert into offerings(kind, slug, name, tagline, description, sort_order) values ('solution', 'mobile-app-development', 'Mobile App Development', 'BUILT, SHIPPED, AND MAINTAINED', 'We build and manage mobile applications from first design through App Store and Play Store release, and keep supporting them after launch.', 7);
insert into offering_sections values ('solution', 'mobile-app-development', 0, 'Native feel, whichever stack fits', 'Depending on your requirements and budget, we build natively for iOS and Android or with a cross-platform framework to cover both from a single codebase, and we''ll tell you honestly which approach fits your project instead of defaulting to whichever is easiest for us.');
insert into offering_sections values ('solution', 'mobile-app-development', 1, 'AI features are increasingly part of the brief', 'A growing share of the mobile apps we build now include an AI-powered layer of some kind: an in-app assistant, smart search, personalized recommendations, or a chatbot for support, built with the same LLM integration work we do for web products.');
insert into offering_sections values ('solution', 'mobile-app-development', 2, 'From design through to the app stores', 'UI/UX design, development, testing across devices, and the submission process for the App Store and Google Play, we manage the parts that are easy to get stuck on if you haven''t shipped a mobile app before.');
insert into offering_sections values ('solution', 'mobile-app-development', 3, 'We don''t disappear after launch', 'Apps need upkeep: OS updates, new device sizes, bug fixes, and new features as your user base grows. We offer ongoing management so your app doesn''t quietly go stale a year after it ships.');
insert into offering_stats values ('solution', 'mobile-app-development', 0, 'Platforms', 'iOS & Android');
insert into offering_stats values ('solution', 'mobile-app-development', 1, 'AI features on request', 'Assistants, search, recommendations');
insert into offering_stats values ('solution', 'mobile-app-development', 2, 'Post-launch support', 'Available');
insert into quiz_questions values ('q1', 0, 'How is your business currently handling repetitive customer or internal questions?');
insert into quiz_options(question_id, position, label) values ('q1', 0, 'Entirely by hand — email, phone, or a shared inbox');
insert into quiz_options(question_id, position, label) values ('q1', 1, 'A basic FAQ page or static help center');
insert into quiz_options(question_id, position, label) values ('q1', 2, 'A simple rules-based chatbot with limited answers');
insert into quiz_options(question_id, position, label) values ('q1', 3, 'No AI or chatbot yet, but actively exploring options');
insert into quiz_questions values ('q2', 1, 'How much of your team''s time goes into manual, repetitive digital tasks each week?');
insert into quiz_options(question_id, position, label) values ('q2', 0, 'More than half — it''s a significant drag on productivity');
insert into quiz_options(question_id, position, label) values ('q2', 1, 'A meaningful chunk, but manageable for now');
insert into quiz_options(question_id, position, label) values ('q2', 2, 'A small amount, mostly automated already');
insert into quiz_options(question_id, position, label) values ('q2', 3, 'Not sure — nobody''s actually measured it');
insert into quiz_questions values ('q3', 2, 'What''s your team''s current comfort level with AI/LLM tools like ChatGPT or Claude?');
